gOF(){return"\u041f\u0435\u0440\u0435\u0442\u044f\u0433\u043d\u0456\u0442\u044c \u0432\u0456\u0434\u0434\u0456\u043b\u0438 \u0432 \u043f\u043e\u0440\u044f\u0434\u043a\u0443, \u0432 \u044f\u043a\u043e\u043c\u0443 \u0432\u0438 \u043e\u0431\u0445\u043e\u0434\u0438\u0442\u0435 \u043c\u0430\u0433\u0430\u0437\u0438\u043d. \u0421\u043f\u0438\u0441\u043e\u043a \u0456 \u0440\u0435\u0436\u0438\u043c \xab\u0423 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0456\xbb \u043f\u0456\u0434\u0443\u0442\u044c \u0446\u0438\u043c \u043c\u0430\u0440\u0448\u0440\u0443\u0442\u043e\u043c."},
