gwk(){return"\u0412\u0430\u0448\u0435 \u0456\u043c\u2019\u044f"},
gFB(){return"\u041d\u0430\u043f\u0440\u0438\u043a\u043b\u0430\u0434, \u0416\u0435\u043d\u044f"},
gPx(){return"\u0406\u043c\u2019\u044f \u0431\u0430\u0447\u0430\u0442\u044c \u0443\u0447\u0430\u0441\u043d\u0438\u043a\u0438 \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u0445 \u0441\u043f\u0438\u0441\u043a\u0456\u0432: \u0445\u0442\u043e \u0437\u0430\u0440\u0430\u0437 \u043f\u0435\u0440\u0435\u0433\u043b\u044f\u0434\u0430\u0454 \u0441\u043f\u0438\u0441\u043e\u043a \u0456 \u0445\u0442\u043e \u043f\u043e\u0437\u043d\u0430\u0447\u0438\u0432 \u0442\u043e\u0432\u0430\u0440. \u0417\u0431\u0435\u0440\u0456\u0433\u0430\u0454\u0442\u044c\u0441\u044f \u0432 \u0445\u043c\u0430\u0440\u0456 \u043b\u0438\u0448\u0435 \u0434\u043b\u044f \u0441\u043f\u0438\u0441\u043a\u0456\u0432, \u044f\u043a\u0438\u043c\u0438 \u0432\u0438 \u043f\u043e\u0434\u0456\u043b\u0438\u043b\u0438\u0441\u044f."},
gPy(){return"\u0406\u043c\u2019\u044f \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043e"},
gPi(){return"\u0417\u0430\u0440\u0430\u0437 \u043f\u0435\u0440\u0435\u0433\u043b\u044f\u0434\u0430\u044e\u0442\u044c"},
gwB(){return"\u0425\u0442\u043e\u0441\u044c"},
gyK(){return"\u041c\u043e\u0432\u0430"},
gNb(){return"\u0421\u043f\u0438\u0441\u043a\u0438"},
gNd(){return"\u041f\u043e\u043a\u0443\u043f\u043a\u0438"},
gNa(){return"\u0421\u0442\u0432\u043e\u0440\u0438\u0442\u0438"},
gNc(){return"\u041f\u0440\u043e\u0444\u0456\u043b\u044c"},
gOd(){return"\u041f\u0440\u043e\u0444\u0456\u043b\u044c"},
gNk(){return"\u0421\u0442\u0432\u043e\u0440\u0456\u0442\u044c \u0430\u0431\u043e \u0432\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0441\u043f\u0438\u0441\u043e\u043a \u2014 \u0432\u0456\u043d \u0437\u2019\u044f\u0432\u0438\u0442\u044c\u0441\u044f \u0442\u0443\u0442 \u0434\u043b\u044f \u0448\u0432\u0438\u0434\u043a\u043e\u0433\u043e \u0434\u043e\u0441\u0442\u0443\u043f\u0443."},
gJB(){return"\u041f\u0440\u043e \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a"},
Ov(a,b){return a+": \xab"+b+"\xbb \u2014 \u0434\u043e \u043f\u043e\u043a\u0443\u043f\u043a\u0438"},
Os(a,b){return a+": \xab"+b+"\xbb \u2014 \u043a\u0443\u043f\u043b\u0435\u043d\u043e"},
