gK4(){return"\u0410\u043a\u0430\u0443\u043d\u0442 \u043f\u0440\u0438\u0432\u2019\u044f\u0437\u0443\u0454 \u0441\u043f\u0438\u0441\u043a\u0438 \u0434\u043e \u0432\u0430\u0441, \u0430 \u043d\u0435 \u0434\u043e \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u044e: \u0432\u0445\u0456\u0434 \u043d\u0430 \u043d\u043e\u0432\u043e\u043c\u0443 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0456 \u0447\u0438 \u0432 \u0456\u043d\u0448\u043e\u043c\u0443 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0456 \u043f\u043e\u0432\u0435\u0440\u043d\u0435 \u0432\u0441\u0456 \u0432\u0430\u0448\u0456 \u0441\u043f\u0438\u0441\u043a\u0438. \u042f\u043a\u0449\u043e \u0432\u0438 \u0432\u0436\u0435 \u043a\u043e\u0440\u0438\u0441\u0442\u0443\u0432\u0430\u043b\u0438\u0441\u044f \u0441\u043f\u0456\u043b\u044c\u043d\u0438\u043c\u0438 \u0441\u043f\u0438\u0441\u043a\u0430\u043c\u0438 \u0430\u043d\u043e\u043d\u0456\u043c\u043d\u043e, email \u043f\u0440\u0438\u0432\u2019\u044f\u0436\u0435\u0442\u044c\u0441\u044f \u0434\u043e \u043f\u043e\u0442\u043e\u0447\u043d\u043e\u0433\u043e \u0430\u043a\u0430\u0443\u043d\u0442\u0430 \u2014 \u043d\u0456\u0447\u043e\u0433\u043e \u043d\u0435 \u0437\u0430\u0433\u0443\u0431\u0438\u0442\u044c\u0441\u044f."},
gK_(){return"Email"},
gK6(){return"\u041d\u0430\u0434\u0456\u0441\u043b\u0430\u0442\u0438 \u043f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f"},
gK1(){return"\u0426\u0435\u0439 \u0441\u043f\u043e\u0441\u0456\u0431 \u0432\u0445\u043e\u0434\u0443 \u0449\u0435 \u043d\u0435 \u043f\u0456\u0434\u043a\u043b\u044e\u0447\u0435\u043d\u043e. \u0423\u0432\u0456\u0439\u0434\u0456\u0442\u044c \u043f\u043e\u0448\u0442\u043e\u044e."},
