gK3(){return"\u0426\u044f \u043f\u043e\u0448\u0442\u0430 \u0432\u0436\u0435 \u043f\u0440\u0438\u0432\u2019\u044f\u0437\u0430\u043d\u0430 \u0434\u043e \u0456\u043d\u0448\u043e\u0433\u043e \u0430\u043a\u0430\u0443\u043d\u0442\u0430."},
gLk(){return"\u0414\u0435\u0442\u0430\u043b\u044c\u043d\u043e: \u0444\u043e\u0442\u043e, \u0446\u0456\u043d\u0430, \u043a\u0430\u0442\u0435\u0433\u043e\u0440\u0456\u044f"},
gGk(){return"\u0412\u0438\u0439\u0442\u0438"},
K5(a){return"\u041f\u043e\u0441\u0438\u043b\u0430\u043d\u043d\u044f \u0434\u043b\u044f \u0432\u0445\u043e\u0434\u0443 \u043d\u0430\u0434\u0456\u0441\u043b\u0430\u043d\u043e \u043d\u0430 "+a+". \u0412\u0456\u0434\u043a\u0440\u0438\u0439\u0442\u0435 \u0439\u043e\u0433\u043e \u043d\u0430 \u0446\u044c\u043e\u043c\u0443 \u043f\u0440\u0438\u0441\u0442\u0440\u043e\u0457 \u2014 \u0432\u0445\u0456\u0434 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044c\u0441\u044f \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u043d\u043e."},
gE_(){return"\u042f\u043a \u0446\u0435 \u043f\u0440\u0430\u0446\u044e\u0454"},
gNR(){return"\u041f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u0438"},
gEB(){return"\u0414\u0430\u043b\u0456"},
gNS(){return"\u041f\u043e\u0447\u0430\u0442\u0438"},
gNI(){return"\u0412\u0456\u0447\u043d\u0438\u0439 \u0441\u043f\u0438\u0441\u043e\u043a"},
gNH(){return"\u0421\u043f\u0438\u0441\u043e\u043a \u2014 \u0432\u0430\u0448 \u043e\u0441\u043e\u0431\u0438\u0441\u0442\u0438\u0439 \u043a\u0430\u0442\u0430\u043b\u043e\u0433 \u0442\u043e\u0432\u0430\u0440\u0456\u0432, \u0432\u0456\u043d \u043d\u0456\u043a\u043e\u043b\u0438 \u043d\u0435 \u043e\u0447\u0438\u0449\u0430\u0454\u0442\u044c\u0441\u044f. \u041f\u0435\u0440\u0435\u0434 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u043e\u043c \u043f\u043e\u0437\u043d\u0430\u0447\u0430\u0454\u0442\u0435, \u0449\u043e \u0442\u0440\u0435\u0431\u0430 \u043a\u0443\u043f\u0438\u0442\u0438, \u2014 \u0440\u0435\u0448\u0442\u0430 \u0441\u043f\u043e\u043a\u0456\u0439\u043d\u043e \u0447\u0435\u043a\u0430\u0454 \u0441\u0432\u043e\u0433\u043e \u0447\u0430\u0441\u0443."},
gNK(){return"\u041e\u0434\u0438\u043d \u0442\u0430\u043f \u2014 \u043e\u0434\u043d\u0430 \u0434\u0456\u044f"},
gNJ(){return"\u0422\u0430\u043f \u043f\u043e \u0442\u043e\u0432\u0430\u0440\u0443: \xab\u0434\u043e \u043f\u043e\u043a\u0443\u043f\u043a\u0438\xbb \u2192 \xab\u043a\u0443\u043f\u043b\u0435\u043d\u043e\xbb (\u043f\u0435\u0440\u0435\u043a\u0440\u0435\u0441\u043b\u0435\u043d\u0438\u0439, \u043b\u0438\u0448\u0430\u0454\u0442\u044c\u0441\u044f \u043d\u0430 \u043c\u0456\u0441\u0446\u0456). \u0414\u043e\u0432\u0433\u0435 \u043d\u0430\u0442\u0438\u0441\u043a\u0430\u043d\u043d\u044f \u2014 \u0437\u043d\u044f\u0442\u0438 \u043f\u043e\u0437\u043d\u0430\u0447\u043a\u0443 \u0437\u043e\u0432\u0441\u0456\u043c. \u0421\u0432\u0430\u0439\u043f \u043b\u0456\u0432\u043e\u0440\u0443\u0447 \u2014 \u0432\u0438\u0434\u0430\u043b\u0438\u0442\u0438 \u0437\u0456 \u0441\u043f\u0438\u0441\u043a\u0443."},
gNM(){return"\u041f\u043e\u0445\u0456\u0434 \u0443 \u043c\u0430\u0433\u0430\u0437\u0438\u043d"},
gNL(){return"\u0420\u0435\u0436\u0438\u043c \xab\u0423 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0456\xbb \u043f\u043e\u043a\u0430\u0437\u0443\u0454 \u043b\u0438\u0448\u0435 \u0441\u044c\u043e\u0433\u043e\u0434\u043d\u0456\u0448\u043d\u0456 \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u2014 \u0432\u0435\u043b\u0438\u043a\u0438\u043c \u0448\u0440\u0438\u0444\u0442\u043e\u043c, \u0456 \u0435\u043a\u0440\u0430\u043d \u043d\u0435 \u0433\u0430\u0441\u043d\u0435. \u041f\u0456\u0441\u043b\u044f \u043a\u0430\u0441\u0438 \u0442\u0438\u0441\u043d\u0456\u0442\u044c \xab\u041d\u043e\u0432\u0438\u0439 \u043f\u043e\u0445\u0456\u0434\xbb: \u043a\u0443\u043f\u043b\u0435\u043d\u0435 \u043f\u0456\u0434\u0435 \u0432 \u0456\u0441\u0442\u043e\u0440\u0456\u044e \u0437 \u0447\u0435\u043a\u0430\u043c\u0438 \u0442\u0430 \u0430\u043d\u0430\u043b\u0456\u0442\u0438\u043a\u043e\u044e \u0432\u0438\u0442\u0440\u0430\u0442."},
gNO(){return"\u0412\u0432\u0435\u0434\u0435\u043d\u043d\u044f \u0437\u0430 2 \u0441\u0435\u043a\u0443\u043d\u0434\u0438"},
